# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİN, BİREY VE TOPLUM İLİŞKİSİ (8.3.1)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Din Kavramı ve Fıtrat</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" fill="#1e3a8a">• Akıl sahiplerini kendi özgür</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#1e3a8a">iradeleriyle dünya ve ahiret</text>\n  <text x="125" y="132" text-anchor="middle" font-size="11" fill="#1e3a8a">mutluluğuna ulaştıran ilahi kanun.</text>\n  <text x="125" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Fıtrat (Doğuştan Eğilim):</text>\n  <text x="125" y="180" text-anchor="middle" font-size="11" fill="#1e3a8a">İnsanın yaratılıştan yüce bir</text>\n  <text x="125" y="198" text-anchor="middle" font-size="11" fill="#1e3a8a">yaratıcıya inanma yeteneği</text>\n  <text x="125" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">(Rûm suresi, 30. ayet)</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Din ve Birey</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" fill="#14532d">• Hayata anlam ve amaç katar.</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#14532d">• \'Kimim, niçin yaratıldım?\'</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#14532d">sorularına cevap verir.</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" fill="#14532d">• Ümitsizlik, yalnızlık ve</text>\n  <text x="350" y="182" text-anchor="middle" font-size="11" fill="#14532d">korkuya karşı iç huzuru,</text>\n  <text x="350" y="200" text-anchor="middle" font-size="11" fill="#14532d">sabır ve tevekkül kazandırır.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Manevi ve Ahlaki Olgunluk</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Din ve Toplum</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" fill="#713f12">• Adalet, yardımlaşma, güven</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#713f12">ve kardeşlik ilkelerini yayar.</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" fill="#713f12">• Kul hakkı bilinciyle suç ve</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#713f12">haksızlıkları önler.</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11" fill="#713f12">• Gelenek, mimari, edebiyat ve</text>\n  <text x="575" y="202" text-anchor="middle" font-size="11" fill="#713f12">mûsikimizi besleyerek</text>\n  <text x="575" y="222" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">Toplumsal Birlik Oluşturur</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİNİN TEMEL GAYESİ: ZARÛRÂT-I HAMSE (BEŞ TEMEL ESAS — 8.3.2)</text>\n  <rect x="15" y="45" width="126" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="78" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">1. Canın</text>\n  <text x="78" y="84" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">Korunması</text>\n  <text x="78" y="110" text-anchor="middle" font-size="10" fill="#881337">Yaşama hakkı</text>\n  <text x="78" y="126" text-anchor="middle" font-size="10" fill="#881337">dokunulmazdır.</text>\n  <text x="78" y="150" text-anchor="middle" font-size="10" fill="#881337">Cinayet, intihar,</text>\n  <text x="78" y="166" text-anchor="middle" font-size="10" fill="#881337">kan davası yasaktır.</text>\n  <text x="78" y="194" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">İş sağlığı ve</text>\n  <text x="78" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">güvenliği esastır.</text>\n  <text x="78" y="230" text-anchor="middle" font-size="9" fill="#be123c">(Mâide, 32)</text>\n\n  <rect x="151" y="45" width="126" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="214" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">2. Aklın</text>\n  <text x="214" y="84" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Korunması</text>\n  <text x="214" y="110" text-anchor="middle" font-size="10" fill="#1e3a8a">Akıl, dinî</text>\n  <text x="214" y="126" text-anchor="middle" font-size="10" fill="#1e3a8a">sorumluluğun</text>\n  <text x="214" y="142" text-anchor="middle" font-size="10" fill="#1e3a8a">ön şartıdır.</text>\n  <text x="214" y="168" text-anchor="middle" font-size="10" fill="#1e3a8a">Alkol, uyuşturucu</text>\n  <text x="214" y="184" text-anchor="middle" font-size="10" fill="#1e3a8a">ve zararlı maddeler</text>\n  <text x="214" y="200" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">haram kılınmıştır.</text>\n  <text x="214" y="230" text-anchor="middle" font-size="9" fill="#1d4ed8">(Mâide, 90)</text>\n\n  <rect x="287" y="45" width="126" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. Dinin</text>\n  <text x="350" y="84" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Korunması</text>\n  <text x="350" y="110" text-anchor="middle" font-size="10" fill="#14532d">Kur\'an ve sünnete</text>\n  <text x="350" y="126" text-anchor="middle" font-size="10" fill="#14532d">dayalı sahih bilgi</text>\n  <text x="350" y="142" text-anchor="middle" font-size="10" fill="#14532d">esas alınır.</text>\n  <text x="350" y="168" text-anchor="middle" font-size="10" fill="#14532d">Bid\'at, hurafe, batıl</text>\n  <text x="350" y="184" text-anchor="middle" font-size="10" fill="#14532d">inanç ve din</text>\n  <text x="350" y="200" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">istismarı önlenir.</text>\n  <text x="350" y="230" text-anchor="middle" font-size="9" fill="#15803d">(Bakara, 256)</text>\n\n  <rect x="423" y="45" width="126" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="486" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">4. Neslin</text>\n  <text x="486" y="84" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Korunması</text>\n  <text x="486" y="110" text-anchor="middle" font-size="10" fill="#713f12">Sağlıklı toplum</text>\n  <text x="486" y="126" text-anchor="middle" font-size="10" fill="#713f12">sağlıklı aile ile</text>\n  <text x="486" y="142" text-anchor="middle" font-size="10" fill="#713f12">kurulur.</text>\n  <text x="486" y="168" text-anchor="middle" font-size="10" fill="#713f12">Nikâh ve aile kurumu</text>\n  <text x="486" y="184" text-anchor="middle" font-size="10" fill="#713f12">teşvik edilir; zina</text>\n  <text x="486" y="200" text-anchor="middle" font-size="10" font-weight="bold" fill="#a16207">ve iffetsizlik yasaktır.</text>\n  <text x="486" y="230" text-anchor="middle" font-size="9" fill="#a16207">(Rûm, 21)</text>\n\n  <rect x="559" y="45" width="126" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="622" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">5. Malın</text>\n  <text x="622" y="84" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">Korunması</text>\n  <text x="622" y="110" text-anchor="middle" font-size="10" fill="#581c87">Helal kazanç, emek</text>\n  <text x="622" y="126" text-anchor="middle" font-size="10" fill="#581c87">ve mülkiyet hakkı</text>\n  <text x="622" y="142" text-anchor="middle" font-size="10" fill="#581c87">güvence altındadır.</text>\n  <text x="622" y="168" text-anchor="middle" font-size="10" fill="#581c87">Hırsızlık, rüşvet, faiz,</text>\n  <text x="622" y="184" text-anchor="middle" font-size="10" fill="#581c87">kumar, karaborsa ve</text>\n  <text x="622" y="200" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">israf yasaklanmıştır.</text>\n  <text x="622" y="230" text-anchor="middle" font-size="9" fill="#7e22ce">(Bakara, 188)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZARÛRÂT-I HAMSE: KORUYUCU EMİRLER VE YASAKLAR TABLOSU</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Teşvik Edilen Olumlu İlkeler</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" fill="#164e63">• Can: Sağlığı korumak, tedavi olmak, iş güvenliği</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11" fill="#164e63">• Akıl: İlim öğrenmek, tefekkür etmek, okumak</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11" fill="#164e63">• Din: İbadet etmek, Kur\'an ve sünneti öğrenmek</text>\n  <text x="180" y="174" text-anchor="middle" font-size="11" fill="#164e63">• Nesil: Aile kurmak, çocuklara güzel terbiye vermek</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" fill="#164e63">• Mal: Alın teriyle çalışmak, zekât ve sadaka vermek</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Hedef: Dünya ve Ahiret Mutluluğu (Saadet-i Dâreyn)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Yasaklanan Zararlı Davranışlar</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" fill="#881337">• Can: Cinayet, intihar, şiddet, kan davası</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11" fill="#881337">• Akıl: İçki (alkol), uyuşturucu madde, bağımlılık</text>\n  <text x="520" y="148" text-anchor="middle" font-size="11" fill="#881337">• Din: Şirk, hurafe, batıl inanç, bid\'at, istismar</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#881337">• Nesil: Zina, fuhuş, aile içi ihmal ve şiddet</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" fill="#881337">• Mal: Hırsızlık, faiz, kumar, rüşvet, ölçüde hile</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">İlke: Zararı Gidermek ve Hakkı Korumak</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
